    Body.CoefficientOfRestitution = 1.0f;
    Body.InverseBodyInertiaTensor.E11 = 3.0f / ((y * y + z * z) * mass);
    Body.InverseBodyInertiaTensor.E22 = 3.0f / ((x * x + z * z) * mass);
    Body.InverseBodyInertiaTensor.E33 = (3.0f / ((x * x + y * y) * mass));
